SourceCode.Declaration:
/// <summary>
/// One counting line for DIRECT transfer mode. Deliberately carries no on-hand, counted or
/// variance quantity - the counter never sees system stock (blind counting).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDirectLineRow
{
    real lineNumber;
    str  itemNumber;
    str  itemName;
    str  siteId;
    str  warehouseId;
    str  locationId;
    str  batchId;
    str  serialId;
    int  passNumber;

    boolean recount;
}

Method.Source:
[DataMemberAttribute('LineNumber')]
public real parmLineNumber(real _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('ItemNumber')]
public str parmItemNumber(str _value = itemNumber)
{
    itemNumber = _value;
    return itemNumber;
}

[DataMemberAttribute('ItemName')]
public str parmItemName(str _value = itemName)
{
    itemName = _value;
    return itemName;
}

[DataMemberAttribute('SiteId')]
public str parmSiteId(str _value = siteId)
{
    siteId = _value;
    return siteId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}

[DataMemberAttribute('BatchId')]
public str parmBatchId(str _value = batchId)
{
    batchId = _value;
    return batchId;
}

[DataMemberAttribute('SerialId')]
public str parmSerialId(str _value = serialId)
{
    serialId = _value;
    return serialId;
}

[DataMemberAttribute('PassNumber')]
public int parmPassNumber(int _value = passNumber)
{
    passNumber = _value;
    return passNumber;
}

/// <summary>
/// This line is to be counted again (a recount pass).
/// </summary>
[DataMemberAttribute('Recount')]
public boolean parmRecount(boolean _value = recount)
{
    recount = _value;
    return recount;
}
